n3 = tex3D(sampler_noisevol_hq,vec3 (uv2.x * 4.0,uv2.y * 4.0,zv * 3.0)).b;
n4 = tex3D(sampler_noisevol_hq,vec3 (uv2.x * 8.0,uv2.y * 8.0,zv * 7.0)).b;
